ext.badge.title:
.input {$count :number}
.match $count
0 {{auto: no invoice to check}}
one {{auto: {$count} invoice to check}}
* {{auto: {$count} invoices to check}}

ext.deposit.review.message:
.input {$count :number}
.match $count
0 {{{$summary} received: some points to check in auto.}}
one {{{$summary} received: {$count} point to check in auto.}}
* {{{$summary} received: {$count} points to check in auto.}}

ext.popup.some:
.input {$count :number}
.match $count
one {{{$company}: {$count} invoice to check.}}
* {{{$company}: {$count} invoices to check.}}

ext.popup.some_anonymous:
.input {$count :number}
.match $count
one {{{$count} invoice to check.}}
* {{{$count} invoices to check.}}
